export function RecurringEvent({
  title = "{{title}}",
  time = "{{time}}",
  frequency = "{{frequency}}",
  hasEndDate = {{hasEndDate}},
  accent = "{{accent}}",
}) {
  return (
    <div style={{ font: "14px/1.4 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", width: 320, padding: "14px 16px", borderRadius: 10, borderLeft: `4px solid ${accent}`, boxSizing: "border-box", boxShadow: "0 4px 12px rgba(36,20,48,.08)" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 8, color: "#24143077" }}>
        <svg width="14" height="14" viewBox="0 0 16 16" aria-hidden="true"><path d="M4 5h6a3 3 0 0 1 3 3v1M12 11H6a3 3 0 0 1-3-3V7" fill="none" stroke="currentColor" strokeWidth="1.4" /><path d="M2 5l2-2 2 2M14 11l-2 2-2-2" fill="none" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" strokeLinejoin="round" /></svg>
        <p style={{ margin: 0, fontWeight: 700, color: "#241430" }}>{title}</p>
      </div>
      <p style={{ margin: "6px 0 0", fontSize: 12, color: "#24143099" }}>
        <time dateTime="2026-08-18T09:00">{time}</time> &middot; Repeats <span style={{ fontWeight: 700, color: "#241430" }}>{frequency}</span>
      </p>
      {hasEndDate && <p style={{ margin: "4px 0 0", fontSize: 12, color: "#24143099" }}>Ends <time dateTime="2026-12-31">31 Dec 2026</time></p>}
    </div>
  );
}
